CREATE VIEW family_entitlement_sources AS SELECT a.id account_id,a.account_number,a.customer_id,a.store_id,a.package_id,a.package_version,p.name package_name,p.kind,coalesce(max(e.revision),0) revision,coalesce(sum(CASE WHEN e.origin='paid' AND e.action='grant' THEN CASE WHEN p.kind='count' THEN e.quantity ELSE 1 END ELSE 0 END),0) paid_recorded,coalesce(sum(CASE WHEN e.origin='paid' AND e.action='reverse' THEN CASE WHEN p.kind='count' THEN e.quantity ELSE 1 END ELSE 0 END),0) paid_reversed,coalesce(sum(CASE WHEN e.origin='gift' AND e.action='grant' THEN CASE WHEN p.kind='count' THEN e.quantity ELSE 1 END ELSE 0 END),0) gift_recorded,coalesce(sum(CASE WHEN e.origin='gift' AND e.action='reverse' THEN CASE WHEN p.kind='count' THEN e.quantity ELSE 1 END ELSE 0 END),0) gift_reversed FROM entitlement_accounts a JOIN entitlement_package_versions p ON p.package_id=a.package_id AND p.version=a.package_version LEFT JOIN entitlement_events e ON e.account_id=a.id  GROUP BY a.id;
CREATE TABLE family_share_roots(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),recipient_id TEXT NOT NULL REFERENCES users(id),serial INTEGER NOT NULL CHECK(serial>0),record_number TEXT NOT NULL,first_version_id TEXT NOT NULL UNIQUE REFERENCES family_share_versions(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,record_number),FOREIGN KEY(first_version_id,id) REFERENCES family_share_versions(id,root_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE family_share_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_share_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),event_id TEXT NOT NULL UNIQUE REFERENCES family_share_events(id) DEFERRABLE INITIALLY DEFERRED,entitlement_sequence INTEGER NOT NULL CHECK(entitlement_sequence>=0),recipient_snapshot_json TEXT NOT NULL CHECK(json_valid(recipient_snapshot_json)),title TEXT NOT NULL,family_note TEXT NOT NULL,item_count INTEGER NOT NULL CHECK(item_count BETWEEN 0 AND 20),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version),UNIQUE(id,root_id),FOREIGN KEY(event_id,id) REFERENCES family_share_events(id,version_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE family_share_items(version_id TEXT NOT NULL REFERENCES family_share_versions(id),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 20),account_id TEXT NOT NULL REFERENCES entitlement_accounts(id),account_revision INTEGER NOT NULL CHECK(account_revision>0),source_snapshot_json TEXT NOT NULL CHECK(json_valid(source_snapshot_json)),PRIMARY KEY(version_id,position),UNIQUE(version_id,account_id));
CREATE TABLE family_share_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_share_roots(id),version_id TEXT NOT NULL REFERENCES family_share_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('publish','withdraw')),status TEXT NOT NULL CHECK(status IN('published','withdrawn')),reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,version_id));
CREATE VIEW family_share_current AS SELECT * FROM family_share_events e WHERE revision=(SELECT max(revision) FROM family_share_events WHERE root_id=e.root_id);
CREATE TRIGGER family_share_root_source BEFORE INSERT ON family_share_roots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM customers c JOIN users u ON u.id=NEW.recipient_id JOIN guardian_links g ON g.user_id=u.id AND g.customer_id=c.id LEFT JOIN user_security s ON s.user_id=u.id WHERE c.id=NEW.customer_id AND c.store_id=NEW.store_id AND u.role='guardian' AND u.active=1 AND g.active=1 AND coalesce(s.must_change_password,0)=0 AND c.created_at<=NEW.created_at) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM family_share_roots WHERE store_id=NEW.store_id),1) OR NEW.record_number IS NOT 'FS-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'family publication fixed current customer/recipient/store/number') END;END;
CREATE TRIGGER family_share_version_source BEFORE INSERT ON family_share_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_share_roots r JOIN users u ON u.id=r.recipient_id JOIN guardian_links g ON g.user_id=u.id AND g.customer_id=r.customer_id LEFT JOIN user_security s ON s.user_id=u.id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND u.role='guardian' AND u.active=1 AND g.active=1 AND coalesce(s.must_change_password,0)=0 AND NEW.recipient_snapshot_json=json_object('id',u.id,'display_name',u.display_name,'role',u.role,'active',u.active,'security_revision',coalesce(s.revision,1),'must_change_password',coalesce(s.must_change_password,0)) AND NEW.entitlement_sequence=coalesce((SELECT max(sequence) FROM entitlement_events WHERE customer_id=r.customer_id),0)) OR EXISTS(SELECT 1 FROM family_share_roots r JOIN entitlement_events x ON x.customer_id=r.customer_id WHERE r.id=NEW.root_id AND x.created_at>NEW.created_at) OR NEW.version<>coalesce((SELECT max(version)+1 FROM family_share_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM family_share_events WHERE store_id=NEW.store_id),0) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM family_share_roots r WHERE r.id=NEW.root_id AND r.first_version_id=NEW.id AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by) THEN RAISE(ABORT,'family publication current named recipient/version pairing') END;END;
CREATE TRIGGER family_share_item_source BEFORE INSERT ON family_share_items BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_share_versions v JOIN family_share_roots r ON r.id=v.root_id JOIN family_entitlement_sources m ON m.customer_id=r.customer_id AND m.store_id=r.store_id AND m.account_id=NEW.account_id WHERE v.id=NEW.version_id AND NEW.account_revision=m.revision AND NEW.source_snapshot_json=json_object('account_id',m.account_id,'account_number',m.account_number,'customer_id',m.customer_id,'store_id',m.store_id,'package_id',m.package_id,'package_version',m.package_version,'package_name',m.package_name,'kind',m.kind,'revision',m.revision,'paid_recorded',m.paid_recorded,'paid_reversed',m.paid_reversed,'gift_recorded',m.gift_recorded,'gift_reversed',m.gift_reversed) AND NEW.position<=v.item_count AND v.entitlement_sequence=coalesce((SELECT max(sequence) FROM entitlement_events WHERE customer_id=r.customer_id),0) AND NOT EXISTS(SELECT 1 FROM family_share_events WHERE version_id=v.id)) THEN RAISE(ABORT,'family fixed original entitlement source/current complete published facts') END;END;
CREATE TRIGGER family_share_event_source BEFORE INSERT ON family_share_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_share_versions v WHERE v.id=NEW.version_id AND v.root_id=NEW.root_id AND v.store_id=NEW.store_id) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM family_share_events WHERE store_id=NEW.store_id),1) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM family_share_events WHERE root_id=NEW.root_id),1) OR NEW.action='publish' AND (NEW.status<>'published' OR NOT EXISTS(SELECT 1 FROM family_share_versions v WHERE v.id=NEW.version_id AND v.event_id=NEW.id AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.reason=NEW.reason AND v.item_count=(SELECT count(*) FROM family_share_items WHERE version_id=v.id) AND EXISTS(SELECT 1 FROM family_share_roots r JOIN users u ON u.id=r.recipient_id JOIN guardian_links g ON g.user_id=u.id AND g.customer_id=r.customer_id LEFT JOIN user_security s ON s.user_id=u.id WHERE r.id=v.root_id AND g.active=1 AND u.role='guardian' AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND v.recipient_snapshot_json=json_object('id',u.id,'display_name',u.display_name,'role',u.role,'active',u.active,'security_revision',coalesce(s.revision,1),'must_change_password',coalesce(s.must_change_password,0)) AND v.entitlement_sequence=coalesce((SELECT max(sequence) FROM entitlement_events WHERE customer_id=r.customer_id),0)) AND v.version=coalesce((SELECT max(v2.version)+1 FROM family_share_events e JOIN family_share_versions v2 ON v2.id=e.version_id WHERE e.root_id=NEW.root_id),1))) THEN RAISE(ABORT,'family publication complete paired event') END;
SELECT CASE WHEN NEW.action='withdraw' AND (NEW.status<>'withdrawn' OR NOT EXISTS(SELECT 1 FROM family_share_current e WHERE e.root_id=NEW.root_id AND e.status='published' AND e.version_id=NEW.version_id)) THEN RAISE(ABORT,'family current publication explicit withdrawal') END;END;
CREATE TRIGGER family_share_roots_actor BEFORE INSERT ON family_share_roots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_share_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family publication current actor/time');END;
CREATE TRIGGER family_share_roots_no_update BEFORE UPDATE ON family_share_roots BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_roots_no_delete BEFORE DELETE ON family_share_roots BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_versions_actor BEFORE INSERT ON family_share_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_share_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family publication current actor/time');END;
CREATE TRIGGER family_share_versions_no_update BEFORE UPDATE ON family_share_versions BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_versions_no_delete BEFORE DELETE ON family_share_versions BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_versions_text BEFORE INSERT ON family_share_versions WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 OR length(trim(NEW.family_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.family_note)>2000 OR instr(NEW.family_note,char(0))>0 BEGIN SELECT RAISE(ABORT,'family publication explicit selected content');END;
CREATE TRIGGER family_share_items_no_update BEFORE UPDATE ON family_share_items BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_items_no_delete BEFORE DELETE ON family_share_items BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_events_actor BEFORE INSERT ON family_share_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_share_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family publication current actor/time');END;
CREATE TRIGGER family_share_events_no_update BEFORE UPDATE ON family_share_events BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_events_no_delete BEFORE DELETE ON family_share_events BEGIN SELECT RAISE(ABORT,'family publication immutable');END;
CREATE TRIGGER family_share_events_text BEFORE INSERT ON family_share_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 OR instr(NEW.next_step,char(0))>0 BEGIN SELECT RAISE(ABORT,'family publication explicit selected content');END;
